import os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SEAL = {'mit': ('MIT', '#a31f34'), 'imperial': ('IC', '#003e74'), 'stanford': ('SU', '#8c1515'), 'oxford': ('OX', '#002147'), 'harvard': ('H', '#a51c30'), 'cambridge': ('CAM', '#4f8a74'), 'caltech': ('CIT', '#e8630a'), 'eth': ('ETH', '#1f407a'), 'ucl': ('UCL', '#500778'), 'nus': ('NUS', '#ef7c00')}
def seal(k):
    if os.path.exists(os.path.join(ROOT, "photos", "unis", k + ".png")):
        return f'<span class="seal img"><img src="{{UP}}photos/unis/{k}.png" alt=""></span>'
    ab, col = SEAL[k]; fs = 15 if len(ab) <= 2 else 12 if len(ab) == 3 else 9.5
    return (f'<span class="seal" style="--sc:{col}"><svg viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="22" class="s1"/>'
            f'<circle cx="24" cy="24" r="17.5" class="s2"/><text x="24" y="{24 + fs * .36:.1f}" text-anchor="middle" font-size="{fs}">{ab}</text></svg></span>')

def body(i, tabs_html):
    ru = i == 3
    cards = ""
    for k, u in enumerate(UNIS):
        found = L["found_ox"][i] if u["y"] == "ox" else L["founded"][i].format(y=u["y"])
        rows = f'<div class="trow"><span>{L["plat"][i]}</span><b>{u["plat"]}</b></div>'
        if u["fee"]: rows += f'<div class="trow"><span>{L["fee"][i]}</span><b>{u["fee"]}</b></div>'
        if u["dls"]:
            rows += f'<div class="trow"><span>{L["dl"][i]}</span><div class="tdl">' + "".join(f'<span class="cchip">{L["dls"][d][i]} <b>{dt}</b></span>' for d, dt in u["dls"]) + '</div></div>'
        sec = lambda h, items: f'<h4>{h}</h4><ul>' + "".join(f"<li>{x}</li>" for x in items) + '</ul>' if items else ""
        cards += (f'<details class="uni card"{" open" if k == 0 else ""}><summary><span class="ulogo">{seal(u["key"])}<span class="urank">{u["n"]}</span></span><span class="uname"><b>{u["name"][1] if ru else u["name"][0]}</b>'
                  f'<small>{u["city"][1] if ru else u["city"][0]}, {L["countries"][u["c"]][i]} · {found}</small></span></summary>'
                  f'<div class="ubody"><div class="urk">{L["rank"][i].format(n=u["n"])}</div><h4>{L["s_apply"][i]}</h4>{rows}'
                  f'{sec(L["s_tests"][i], [P[x][i] for x in u["tests"]])}{sec(L["s_english"][i], [P[u["eng"]][i]])}'
                  f'{sec(L["s_money"][i], [P[x][i] for x in u["money"]])}{sec(L["s_know"][i], [P[x][i] for x in u["know"]])}'
                  f'<a class="uofficial" href="{u["url"]}" rel="noopener">{L["official"][i]}</a></div></details>')
    return f'{tabs_html}<p class="lead2">{L["intro"][i]}</p><p class="note">{L["warn"][i]}</p><div class="unis">{cards}</div>'
